import type { VendorQuoteAdapterInput } from "../types.js";
import {
  providerDispatchAuthorizationDenial,
  type ProviderDispatchAuthorizationDenial,
} from "./providerDispatchAuthorization.js";

/**
 * Generated by `npm run fixture:onboard -- oshcut --stage=live` (OVD-687).
 *
 * Adapter-side binding for production OSH Cut launches: the shared
 * provider check (`providerDispatchAuthorization.ts`) bound to the
 * OSH Cut envelope identity. The identity is NOT reviewed: it is absent
 * from `REVIEWED_PROVIDER_DISPATCH_ENVELOPES` and has no review row, so no
 * permit can name it. Declaring it here admits nothing.
 */
export const OSHCUT_DISPATCH_ENVELOPE = Object.freeze({ id: "oshcut-quote-envelope", version: 1 });

export type OshcutDispatchAuthorizationDenial = ProviderDispatchAuthorizationDenial;

export function oshcutDispatchAuthorizationDenial(
  input: VendorQuoteAdapterInput,
  nowMs: number = Date.now(),
): OshcutDispatchAuthorizationDenial | null {
  return providerDispatchAuthorizationDenial(
    input,
    { provider: "oshcut", ...OSHCUT_DISPATCH_ENVELOPE },
    nowMs,
  );
}
